INSERT INTO rating (id, vehicle_score, service_score, comment, is_approved, moderated_by, moderated_at, reservation_id, customer_id, created_by, status_id) VALUES
('ra000000-0000-0000-0000-000000000001', 5, 5, 'Excelente experiencia, el vehiculo estaba impecable y el servicio fue muy rapido. Volvere a rentar sin duda.',     TRUE,  'u1000000-0000-0000-0000-000000000002', NOW() - INTERVAL '19 days', 're000000-0000-0000-0000-000000000001', 'cu000000-0000-0000-0000-000000000001', 'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
('ra000000-0000-0000-0000-000000000002', 4, 5, 'Muy buen servicio, el Corolla es comodo y economico. La sucursal en El Dorado es muy conveniente.',               TRUE,  'u1000000-0000-0000-0000-000000000002', NOW() - INTERVAL '9 days',  're000000-0000-0000-0000-000000000002', 'cu000000-0000-0000-0000-000000000002', 'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
('ra000000-0000-0000-0000-000000000003', 3, 4, 'El Duster estuvo bien pero tenia las llantas algo desgastadas. El personal fue muy amable.',                        FALSE, NULL,                                  NULL,                        're000000-0000-0000-0000-000000000006', 'cu000000-0000-0000-0000-000000000007', 'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
('ra000000-0000-0000-0000-000000000004', 5, 5, 'La Hilux perfecta para nuestro viaje de trabajo, cargamos todos los equipos sin problema. Servicio 10/10.',        TRUE,  'u1000000-0000-0000-0000-000000000002', NOW() - INTERVAL '50 days', 're000000-0000-0000-0000-000000000006', 'cu000000-0000-0000-0000-000000000007', 'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
('ra000000-0000-0000-0000-000000000005', 4, 3, 'El Tucson estuvo bien, pero la entrega tardo mas de lo esperado. El vehiculo en buen estado.',                     TRUE,  'u1000000-0000-0000-0000-000000000002', NOW() - INTERVAL '27 days', 're000000-0000-0000-0000-000000000008', 'cu000000-0000-0000-0000-000000000004', 'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
('ra000000-0000-0000-0000-000000000006', 2, 2, 'El vehiculo tenia problemas con el aire acondicionado desde el primer dia. No hubo atencion rapida al reporte.',   FALSE, NULL,                                  NULL,                        're000000-0000-0000-0000-000000000009', 'cu000000-0000-0000-0000-000000000008', 'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
('ra000000-0000-0000-0000-000000000007', 5, 5, 'El BMW 320i es una maravilla, experiencia de lujo total. El equipo de Renta Movil Medellin es excelente.',         TRUE,  'u1000000-0000-0000-0000-000000000002', NOW() - INTERVAL '1 day',   're000000-0000-0000-0000-000000000004', 'cu000000-0000-0000-0000-000000000006', 'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
('ra000000-0000-0000-0000-000000000008', 4, 4, 'El Carnival fue perfecto para el viaje familiar. Suficiente espacio para todos. Proceso de entrega muy ordenado.', TRUE,  'u1000000-0000-0000-0000-000000000002', NOW() - INTERVAL '4 days',  're000000-0000-0000-0000-000000000005', 'cu000000-0000-0000-0000-000000000005', 'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
('ra000000-0000-0000-0000-000000000009', 5, 5, 'El Corolla en excelente estado. Proceso de reserva online muy facil. Recomendaria Renta Movil a todos.',           FALSE, NULL,                                  NULL,                        're000000-0000-0000-0000-000000000010', 'cu000000-0000-0000-0000-000000000009', 'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
('ra000000-0000-0000-0000-000000000010', 3, 5, 'El Spark es funcional para ciudad, aunque algo pequeno para viaje largo. El servicio al cliente fue excelente.',    TRUE,  'u1000000-0000-0000-0000-000000000002', NOW() - INTERVAL '18 days', 're000000-0000-0000-0000-000000000001', 'cu000000-0000-0000-0000-000000000001', 'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001');
INSERT INTO complaint (id, complaint_type, description, admin_response, auto_closed, closed_at, complaint_state, customer_id, responded_by, created_by, status_id) VALUES
('cq000000-0000-0000-0000-000000000001', 'VEHICLE',  'El vehiculo Mazda 3 presentaba un ruido extrano en el motor desde el primer dia de renta que no fue reportado en la inspeccion inicial.',                                    'Investigamos el caso y confirmamos que el ruido corresponde a una falla preexistente. Ofrecemos disculpas y un descuento del 15% en su proxima reserva.',      FALSE, NOW() - INTERVAL '28 days', 'RESOLVED', 'cu000000-0000-0000-0000-000000000003', 'u1000000-0000-0000-0000-000000000002', 'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
('cq000000-0000-0000-0000-000000000002', 'SERVICE',  'Espere mas de 45 minutos en la sucursal Barranquilla para recibir el vehiculo a pesar de tener reserva confirmada.',                                                       'Lamentamos el inconveniente. Estamos reforzando el equipo de la sucursal Barranquilla. Se aplico un credito de $50.000 a su cuenta.',                         FALSE, NOW() - INTERVAL '10 days', 'RESOLVED', 'cu000000-0000-0000-0000-000000000008', 'u1000000-0000-0000-0000-000000000006', 'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
('cq000000-0000-0000-0000-000000000003', 'BILLING',  'Me cobraron $120.000 por exceso de kilometraje que no corresponde segun el odometro del vehiculo al momento de la devolucion.',                                            NULL,                                                                                                                                                          FALSE, NULL,                        'IN_REVIEW', 'cu000000-0000-0000-0000-000000000004', 'u1000000-0000-0000-0000-000000000006', 'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
('cq000000-0000-0000-0000-000000000004', 'VEHICLE',  'El aire acondicionado del Chevrolet Tracker no funcionaba correctamente durante los 5 dias de renta. Hice el reporte y nadie lo soluciono.',                               'Confirmamos la falla y el reporte del tecnico. Reembolsaremos el 20% del valor de la renta. Disculpe las molestias.',                                          FALSE, NOW() - INTERVAL '5 days',  'RESOLVED', 'cu000000-0000-0000-0000-000000000009', 'u1000000-0000-0000-0000-000000000002', 'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
('cq000000-0000-0000-0000-000000000005', 'SERVICE',  'El agente de la sucursal Cali tuvo un trato muy descortez con mi esposa al momento de entregar el vehiculo.',                                                              NULL,                                                                                                                                                          FALSE, NULL,                        'PENDING',  'cu000000-0000-0000-0000-000000000005', NULL,                                  'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
('cq000000-0000-0000-0000-000000000006', 'BILLING',  'Se realizo un doble cobro en mi tarjeta Visa por la reserva RES-2025-0002.',                                                                                               'Confirmamos el error de cobro. El valor duplicado sera revertido en 3 a 5 dias habiles. Disculpe el inconveniente.',                                          FALSE, NOW() - INTERVAL '8 days',  'RESOLVED', 'cu000000-0000-0000-0000-000000000002', 'u1000000-0000-0000-0000-000000000006', 'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
('cq000000-0000-0000-0000-000000000007', 'OTHER',    'No recibi el comprobante del contrato por correo electronico despues de firmar digitalmente.',                                                                             'El sistema presento una falla puntual en el envio de emails. Ya fue corregida y el comprobante fue reenviado a su correo.',                                    FALSE, NOW() - INTERVAL '3 days',  'CLOSED',   'cu000000-0000-0000-0000-000000000010', 'u1000000-0000-0000-0000-000000000006', 'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
('cq000000-0000-0000-0000-000000000008', 'VEHICLE',  'El Kia Carnival tenia olores muy fuertes en el interior, posiblemente de cigarrillo, a pesar de la politica de no fumar.',                                                NULL,                                                                                                                                                          FALSE, NULL,                        'IN_REVIEW', 'cu000000-0000-0000-0000-000000000005', 'u1000000-0000-0000-0000-000000000006', 'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
('cq000000-0000-0000-0000-000000000009', 'SERVICE',  'La app movil presento fallas al intentar hacer el check-in virtual. Tuve que llamar 3 veces al call center sin respuesta.',                                               'El servicio de check-in virtual presento intermitencia el dia 18 de abril. Fue resuelto y mejoramos la capacidad del servidor.',                               TRUE,  NOW() - INTERVAL '12 days', 'CLOSED',   'cu000000-0000-0000-0000-000000000001', 'u1000000-0000-0000-0000-000000000006', 'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
('cq000000-0000-0000-0000-000000000010', 'BILLING',  'El plan de kilometraje ilimitado que contrate aparece en la factura como plan de 200 km/dia, lo cual es incorrecto.',                                                     NULL,                                                                                                                                                          FALSE, NULL,                        'PENDING',  'cu000000-0000-0000-0000-000000000006', NULL,                                  'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001');
INSERT INTO support_ticket (id, subject, message, ticket_state, agent_response, rating_score, closed_at, customer_id, assigned_to, created_by, status_id) VALUES
('st000000-0000-0000-0000-000000000001', 'Como modifico las fechas de mi reserva?',         'Necesito cambiar las fechas de la reserva RES-2025-0003 del 1 al 5 de mayo al 8 al 12 de mayo. Es posible hacerlo sin penalizacion?',              'CLOSED',      'Si puede modificar las fechas con mas de 48h de anticipacion sin costo adicional. Por favor ingrese a Mi cuenta > Mis Reservas > Modificar. Si necesita ayuda adicional estamos aqui.',                       5, NOW() - INTERVAL '3 days',  'cu000000-0000-0000-0000-000000000003', 'u1000000-0000-0000-0000-000000000006', 'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
('st000000-0000-0000-0000-000000000002', 'No puedo subir mi licencia de conduccion',        'Al intentar cargar la foto de mi licencia en la app me aparece error 413. He intentado varias veces con diferentes formatos.',                     'IN_PROGRESS', 'Hola! El error 413 indica que la imagen supera el limite de 5MB. Por favor comprima la imagen o use JPG en lugar de PNG. Si el problema persiste escribanos.',                                                NULL, NULL,                         'cu000000-0000-0000-0000-000000000007', 'u1000000-0000-0000-0000-000000000006', 'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
('st000000-0000-0000-0000-000000000003', 'Solicito factura electronica de renta pasada',    'Necesito la factura electronica de la reserva RES-2025-0006 para declarar gastos de empresa ante la DIAN. A que correo la pueden enviar?',         'CLOSED',      'Con gusto! La factura electronica fue enviada a jorge.herrera@empresa.co y también estara disponible en su cuenta en la seccion Documentos > Facturas. Cualquier consulta adicional estamos disponibles.', 4, NOW() - INTERVAL '50 days', 'cu000000-0000-0000-0000-000000000007', 'u1000000-0000-0000-0000-000000000006', 'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
('st000000-0000-0000-0000-000000000004', 'El vehiculo tiene poca gasolina al recogerlo',   'Me entregaron el Carnival con la gasolina al 30%. Yo contrate el servicio de Tanque Lleno. Que hago?',                                            'CLOSED',      'Disculpe el inconveniente. Por favor conserve el recibo de la gasolina que ponga y lo reembolsaremos en 24 horas a su metodo de pago original. Gracias por reportarlo.',                                    5, NOW() - INTERVAL '4 days',  'cu000000-0000-0000-0000-000000000005', 'u1000000-0000-0000-0000-000000000006', 'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
('st000000-0000-0000-0000-000000000005', 'Consulta sobre planes corporativos',              'Somos una empresa con 15 empleados que viajan frecuentemente. Tienen algun plan corporativo con descuentos por volumen de rentas mensuales?',       'CLOSED',      'Claro que si! Tenemos planes corporativos desde 10 rentas/mes con hasta el 25% de descuento. Le paso a nuestro ejecutivo de cuentas corporativas para detallar el plan ideal para su empresa.',          5, NOW() - INTERVAL '20 days', 'cu000000-0000-0000-0000-000000000003', 'u1000000-0000-0000-0000-000000000006', 'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
('st000000-0000-0000-0000-000000000006', 'Olvide un objeto dentro del vehiculo',            'Olvide mi cargador de laptop dentro del Toyota Corolla placa XYZ-456. Ya fue devuelto el vehiculo. Es posible recuperarlo?',                        'IN_PROGRESS', 'Estamos verificando con la sucursal si el objeto fue encontrado. Le responderemos en maximo 2 horas habiles.',                                                                                               NULL, NULL,                         'cu000000-0000-0000-0000-000000000002', 'u1000000-0000-0000-0000-000000000006', 'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
('st000000-0000-0000-0000-000000000007', 'Solicito extension de renta activa',              'Necesito extender la reserva RES-2025-0005 del Kia Carnival hasta el 6 de mayo en lugar del 3 de mayo. El vehiculo no esta reservado para esas fechas?', 'OPEN',   NULL,                                                                                                                                                                                                        NULL, NULL,                         'cu000000-0000-0000-0000-000000000005', NULL,                                  'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
('st000000-0000-0000-0000-000000000008', 'No aparece mi reserva en la app',                 'Realice el pago de la reserva RES-2025-0010 hace 2 dias pero no aparece en la seccion Mis Reservas de la app. El cargo si aparece en mi cuenta.',  'CLOSED',      'El sistema tuvo un retraso en la sincronizacion. Ya fue corregido y su reserva RES-2025-0010 esta visible en la app. Disculpe el inconveniente.',                                                           4, NOW() - INTERVAL '1 day',   'cu000000-0000-0000-0000-000000000009', 'u1000000-0000-0000-0000-000000000006', 'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
('st000000-0000-0000-0000-000000000009', 'Como funciona el seguro premium?',                'Quiero entender que cubre exactamente el plan de cobertura Premium antes de tomarlo en mi proxima reserva del BMW 320i.',                           'CLOSED',      'El plan Premium cubre danos propios, terceros y robo sin deducible. Incluye grua 24h y vehiculo de reemplazo si el siniestro supera 8h de reparacion. Lo encontrara detallado en su contrato.',           5, NOW() - INTERVAL '2 days',  'cu000000-0000-0000-0000-000000000006', 'u1000000-0000-0000-0000-000000000006', 'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
('st000000-0000-0000-0000-000000000010', 'Problema con GPS entregado',                      'El dispositivo GPS que recibi con el Spark no enciende. La pantalla esta completamente negra desde el momento de entregarlo.',                      'OPEN',        NULL,                                                                                                                                                                                                        NULL, NULL,                         'cu000000-0000-0000-0000-000000000001', NULL,                                  'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001');
INSERT INTO ticket_message (id, message, is_agent, ticket_id, sender_id, created_by, status_id) VALUES
('tm000000-0000-0000-0000-000000000001', 'Necesito cambiar las fechas de la reserva RES-2025-0003 del 1 al 5 de mayo al 8 al 12 de mayo.',                                     FALSE, 'st000000-0000-0000-0000-000000000001', 'u1000000-0000-0000-0000-000000000003', 'u1000000-0000-0000-0000-000000000003', 'a1000000-0000-0000-0000-000000000001'),
('tm000000-0000-0000-0000-000000000002', 'Claro que si, puede hacerlo sin penalizacion ingresando a la app desde Mi Cuenta > Reservas > Modificar. Cuente con nosotros!',       TRUE,  'st000000-0000-0000-0000-000000000001', 'u1000000-0000-0000-0000-000000000006', 'u1000000-0000-0000-0000-000000000006', 'a1000000-0000-0000-0000-000000000001'),
('tm000000-0000-0000-0000-000000000003', 'Al intentar cargar la foto de mi licencia me aparece error 413.',                                                                      FALSE, 'st000000-0000-0000-0000-000000000002', 'u1000000-0000-0000-0000-000000000007', 'u1000000-0000-0000-0000-000000000007', 'a1000000-0000-0000-0000-000000000001'),
('tm000000-0000-0000-0000-000000000004', 'El error 413 indica imagen mayor a 5MB. Comprima la imagen o use formato JPG. Si persiste escribanos.',                                TRUE,  'st000000-0000-0000-0000-000000000002', 'u1000000-0000-0000-0000-000000000006', 'u1000000-0000-0000-0000-000000000006', 'a1000000-0000-0000-0000-000000000001'),
('tm000000-0000-0000-0000-000000000005', 'Intente reducir el tamano pero sigue el error. El archivo es de 4.8MB en JPG.',                                                        FALSE, 'st000000-0000-0000-0000-000000000002', 'u1000000-0000-0000-0000-000000000007', 'u1000000-0000-0000-0000-000000000007', 'a1000000-0000-0000-0000-000000000001'),
('tm000000-0000-0000-0000-000000000006', 'Gracias por el dato. Escalamos al equipo tecnico. Le avisaremos en menos de 2 horas con la solucion.',                                TRUE,  'st000000-0000-0000-0000-000000000002', 'u1000000-0000-0000-0000-000000000006', 'u1000000-0000-0000-0000-000000000006', 'a1000000-0000-0000-0000-000000000001'),
('tm000000-0000-0000-0000-000000000007', 'Necesito la factura electronica de la reserva RES-2025-0006 para la DIAN.',                                                            FALSE, 'st000000-0000-0000-0000-000000000003', 'u1000000-0000-0000-0000-000000000007', 'u1000000-0000-0000-0000-000000000007', 'a1000000-0000-0000-0000-000000000001'),
('tm000000-0000-0000-0000-000000000008', 'Factura enviada a jorge.herrera@empresa.co. Tambien disponible en Mi Cuenta > Documentos > Facturas.',                                 TRUE,  'st000000-0000-0000-0000-000000000003', 'u1000000-0000-0000-0000-000000000006', 'u1000000-0000-0000-0000-000000000006', 'a1000000-0000-0000-0000-000000000001'),
('tm000000-0000-0000-0000-000000000009', 'Me entregaron el Carnival con la gasolina al 30%, tenia Tanque Lleno contratado.',                                                     FALSE, 'st000000-0000-0000-0000-000000000004', 'u1000000-0000-0000-0000-000000000005', 'u1000000-0000-0000-0000-000000000005', 'a1000000-0000-0000-0000-000000000001'),
('tm000000-0000-0000-0000-000000000010', 'Disculpe! Conserve el recibo de la gasolina que ponga y lo reembolsamos en 24 horas. Gracias por el reporte.',                         TRUE,  'st000000-0000-0000-0000-000000000004', 'u1000000-0000-0000-0000-000000000006', 'u1000000-0000-0000-0000-000000000006', 'a1000000-0000-0000-0000-000000000001');
INSERT INTO notification_type (id, name, template, created_by, status_id) VALUES
('nt000000-0000-0000-0000-000000000001', 'RESERVA_CONFIRMADA',   'Estimado {nombre}, su reserva {codigo} ha sido confirmada para el {fecha_inicio}. Le esperamos en {sucursal}.', 'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
('nt000000-0000-0000-0000-000000000002', 'RESERVA_CANCELADA',    'Estimado {nombre}, su reserva {codigo} ha sido cancelada. Si tiene preguntas contactenos al {telefono}.',        'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
('nt000000-0000-0000-0000-000000000003', 'PAGO_APROBADO',        'Pago aprobado por ${monto} para la reserva {codigo}. Transaccion: {transaccion}. Gracias por su pago.',         'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
('nt000000-0000-0000-0000-000000000004', 'PAGO_RECHAZADO',       'Su pago para la reserva {codigo} fue rechazado. Por favor verifique sus datos de pago e intente de nuevo.',    'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
('nt000000-0000-0000-0000-000000000005', 'LICENCIA_APROBADA',    'Felicitaciones {nombre}! Su licencia de conduccion fue aprobada. Ya puede realizar reservas en Renta Movil.',   'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
('nt000000-0000-0000-0000-000000000006', 'LICENCIA_RECHAZADA',   'Su licencia de conduccion fue rechazada. Motivo: {motivo}. Por favor suba una nueva imagen legible.',           'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
('nt000000-0000-0000-0000-000000000007', 'RECORDATORIO_ENTREGA', 'Recordatorio: Su vehiculo {placa} debe ser devuelto manana {fecha} antes de las {hora} en {sucursal}.',         'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
('nt000000-0000-0000-0000-000000000008', 'TICKET_RESPONDIDO',    'Su ticket #{ticket_id} ha sido respondido por nuestro equipo. Ingrese a la app para ver la respuesta.',         'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
('nt000000-0000-0000-0000-000000000009', 'CONTRATO_DISPONIBLE',  'Su contrato {numero} esta listo para firma digital. Ingrese a Renta Movil para firmarlo antes del {fecha}.',   'u1000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001'),
